package io.clipbridge.android;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.security.keystore.*;
import java.security.KeyStore;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import java.nio.charset.StandardCharsets;
import org.json.*;
public final class BridgeProvider extends ContentProvider {
    static final Uri URI=Uri.parse("content://io.clipbridge.android.bridge");private SharedPreferences prefs;
    public boolean onCreate(){prefs=getContext().getSharedPreferences("bridge",0);return true;}
    private void authorize(){int caller=Binder.getCallingUid();if(caller==android.os.Process.myUid())return;try{if(caller==getContext().getPackageManager().getApplicationInfo("com.android.systemui",0).uid)return;}catch(Exception ignored){}throw new SecurityException();}
    private void own(){if(Binder.getCallingUid()!=android.os.Process.myUid())throw new SecurityException();}
    private SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("clipbridge.config")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("clipbridge.config",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return(SecretKey)store.getKey("clipbridge.config",null);}
    private String wrap(String text)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());return Protocol.encode(c.getIV())+":"+Protocol.encode(c.doFinal(text.getBytes(StandardCharsets.UTF_8)));}
    private String unwrap(String text)throws Exception{String[] parts=text.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Protocol.decode(parts[0])));return new String(c.doFinal(Protocol.decode(parts[1])),StandardCharsets.UTF_8);}
    private JSONArray profiles()throws Exception{if(prefs.contains("profiles"))return new JSONArray(unwrap(prefs.getString("profiles","")));JSONArray list=new JSONArray();if(prefs.contains("config")){JSONObject config=new JSONObject(unwrap(prefs.getString("config","")));JSONObject state=new JSONObject(unwrap(prefs.getString("state","")));Protocol.config(config);Protocol.state(config,state);list.put(new JSONObject().put("config",config).put("state",state).put("enabled",true).put("name",prefs.getString("peerName","")).put("lastSync",prefs.getLong("lastSync",0)));save(list);if(!prefs.edit().remove("config").remove("state").remove("peerName").remove("lastSync").commit())throw new IllegalStateException();}return list;}
    private void save(JSONArray list)throws Exception{if(!prefs.edit().putString("profiles",wrap(list.toString())).commit())throw new IllegalStateException();}
    private JSONObject groupState()throws Exception{return prefs.contains("group-state")?new JSONObject(unwrap(prefs.getString("group-state",""))):GroupStateOps.empty();}
    private void saveGroupState(JSONObject state)throws Exception{if(!prefs.edit().putString("group-state",wrap(state.toString())).putBoolean("has-groups",activeGroups(state)).commit())throw new IllegalStateException();}
    private void applyGroupState(JSONObject state,JSONArray list)throws Exception{GroupStateOps.captureLastSync(state,list);JSONObject stones=prefs.contains("tombstones")?new JSONObject(unwrap(prefs.getString("tombstones",""))):new JSONObject();if(GroupStateOps.apply(state,list,stones)){if(!prefs.edit().putString("tombstones",wrap(stones.toString())).commit())throw new IllegalStateException();save(list);}saveGroupState(state);}
    private boolean activeGroups(JSONObject state)throws Exception{if(!state.has("identity"))return false;String own=state.getJSONObject("identity").getJSONObject("member").getString("id");JSONArray groups=state.getJSONArray("groups");for(int i=0;i<groups.length();i++){JSONObject group=groups.getJSONObject(i);if(group.optLong("publishedSequence")!=group.optLong("sequence")||group.optBoolean("enabled",true)&&!GroupCrypto.contains(group.getJSONArray("removed"),own))return true;}return false;}
    private boolean hasGroups(){return prefs.getBoolean("has-groups",false);}
    private JSONObject find(JSONArray list,String pair)throws Exception{for(int i=0;i<list.length();i++){JSONObject p=list.getJSONObject(i);if(pair==null || p.getJSONObject("config").getString("pair").equals(pair))return p;}return null;}
    private boolean same(JSONObject a,JSONObject b)throws Exception{for(String key:new String[]{"server","pair","device","peer","token","key","username","password","transport"}){String fallback=key.equals("transport")?"relay":"";String av=a.optString(key,fallback),bv=b.optString(key,fallback);if(key.equals("server")){av=av.replaceAll("/+$","");bv=bv.replaceAll("/+$","");}if(!av.equals(bv))return false;}return true;}
    private String installation(){String id=prefs.getString("installation",null);if(id==null){id=java.util.UUID.randomUUID().toString().replace("-","");if(!prefs.edit().putString("installation",id).commit())throw new IllegalStateException();}return id;}
    @Override public synchronized Bundle call(String method,String arg,Bundle extras){authorize();Bundle out=new Bundle();try{
        JSONArray list=profiles();String pair=extras==null?null:extras.getString("pair");JSONObject p=find(list,pair),c=p==null?null:p.getJSONObject("config");
        switch(method){
            case "group-overview":own();out.putString("groups",GroupStateOps.overview(groupState(),list).toString());break;
            case "group-toggle":own();if(extras==null)throw new IllegalArgumentException();boolean groupEnabled=extras.getBoolean("enabled");if(arg.startsWith("legacy:")){for(int n=0;n<list.length();n++){JSONObject row=list.getJSONObject(n);if(row.optString("groupId").isEmpty()&&GroupStateOps.legacyId(row).equals(arg)){row.put("enabled",groupEnabled);if(!groupEnabled)row.getJSONObject("state").remove("pending");}}save(list);}else{JSONObject toggleState=groupState(),toggled=GroupStateOps.find(toggleState,arg);if(toggled==null)throw new IllegalArgumentException();if(GroupCrypto.contains(toggled.getJSONArray("removed"),installation()))throw new IllegalStateException("本机已退出同步组");toggled.put("enabled",groupEnabled);applyGroupState(toggleState,list);}break;
            case "group-load":own();JSONObject gs=groupState();if(arg!=null&&!gs.has("identity")){gs.put("identity",GroupCrypto.identity(installation(),arg));saveGroupState(gs);}out.putByteArray("state",GroupCrypto.bytes(gs.toString()));break;
            case "group-join":case "group-save":own();if(extras==null||extras.getByteArray("group")==null||extras.getByteArray("group").length>200000)throw new IllegalArgumentException();JSONObject updated=new JSONObject(new String(extras.getByteArray("group"),StandardCharsets.UTF_8));JSONObject stateGroup=groupState();if(method.equals("group-join"))GroupStateOps.install(stateGroup,updated);else GroupStateOps.merge(stateGroup,updated);applyGroupState(stateGroup,list);out.putByteArray("state",GroupCrypto.bytes(stateGroup.toString()));break;
            case "group-delete":own();if(arg.startsWith("legacy:")){JSONObject legacyStones=prefs.contains("tombstones")?new JSONObject(unwrap(prefs.getString("tombstones",""))):new JSONObject();for(int n=list.length()-1;n>=0;n--){JSONObject row=list.getJSONObject(n);if(row.optString("groupId").isEmpty()&&GroupStateOps.legacyId(row).equals(arg)){JSONObject replay=row.getJSONObject("state");replay.remove("pending");legacyStones.put(row.getJSONObject("config").getString("pair"),replay);list.remove(n);}}if(!prefs.edit().putString("tombstones",wrap(legacyStones.toString())).commit())throw new IllegalStateException();save(list);break;}JSONObject deleteState=groupState();JSONObject deleting=GroupStateOps.find(deleteState,arg);if(deleting==null)break;if(!GroupCrypto.contains(deleting.getJSONArray("removed"),installation()))throw new IllegalStateException("请先退出同步组");JSONArray retained=new JSONArray(),oldGroups=deleteState.getJSONArray("groups");for(int n=0;n<oldGroups.length();n++)if(!oldGroups.getJSONObject(n).getString("id").equals(arg))retained.put(oldGroups.getJSONObject(n));deleteState.put("groups",retained);JSONArray deletedGroups=deleteState.optJSONArray("deletedGroups");if(deletedGroups==null)deletedGroups=new JSONArray();GroupCrypto.add(deletedGroups,arg);deleteState.put("deletedGroups",deletedGroups);applyGroupState(deleteState,list);break;
            case "group-connect":own();JSONObject reconnect=groupState(),rg=GroupStateOps.find(reconnect,extras.getString("group"));if(rg==null)throw new IllegalArgumentException();String peer=extras.getString("peer");Protocol.id(peer);JSONArray blocked=rg.optJSONArray("suppressedPeers");if(blocked==null)blocked=new JSONArray();for(int n=blocked.length()-1;n>=0;n--)if(peer.equals(blocked.getString(n)))blocked.remove(n);rg.put("suppressedPeers",blocked);applyGroupState(reconnect,list);break;
            case "poll-settings":own();if(extras==null)throw new IllegalArgumentException();int text=extras.getInt("textPollSeconds"),attachment=extras.getInt("attachmentPollSeconds");if(text<1||text>300||attachment<1||attachment>300)throw new IllegalArgumentException("Interval must be 1-300 seconds");if(!prefs.edit().putInt("textPollSeconds",text).putInt("attachmentPollSeconds",attachment).commit())throw new IllegalStateException();break;
            case "profiles":out.putBoolean("hasGroups",hasGroups());JSONArray overview=new JSONArray();for(int i=0;i<list.length();i++){JSONObject row=new JSONObject(list.getJSONObject(i).toString());row.remove("state");overview.put(row);}out.putString("profiles",overview.toString());out.putInt("textPollSeconds",prefs.getInt("textPollSeconds",2));out.putInt("attachmentPollSeconds",prefs.getInt("attachmentPollSeconds",3));out.putString("installation",installation());out.putLong("moduleSeenAt",prefs.getLong("moduleSeenAt",0));out.putBoolean("paused",prefs.getBoolean("paused",false));break;
            case "import":case "replace":own();JSONObject next=new JSONObject(arg);Protocol.config(next);JSONObject old=find(list,next.getString("pair"));if(old!=null){if(!same(old.getJSONObject("config"),next))throw new IllegalArgumentException();old.put("enabled",true);}else{if(list.length()>=16)throw new IllegalArgumentException();JSONObject tombstones=prefs.contains("tombstones")?new JSONObject(unwrap(prefs.getString("tombstones",""))):new JSONObject();JSONObject state=tombstones.optJSONObject(next.getString("pair"));if(state==null)state=new JSONObject().put("clock",0).put("winner","");state.remove("pending");Protocol.state(next,state);list.put(new JSONObject().put("config",next).put("state",state).put("enabled",true));}save(list);break;
            case "toggle":own();JSONObject target=find(list,arg);if(target==null)throw new IllegalArgumentException();target.put("enabled",extras.getBoolean("enabled"));if(!extras.getBoolean("enabled"))target.getJSONObject("state").remove("pending");save(list);break;
            case "delete":own();JSONObject blockedGroups=groupState();for(int n=0;n<list.length();n++){JSONObject row=list.getJSONObject(n);if((arg==null||row.getJSONObject("config").getString("pair").equals(arg))&&!row.optString("groupId").isEmpty()){JSONObject owner=GroupStateOps.find(blockedGroups,row.getString("groupId"));if(owner!=null){JSONArray hiddenRoutes=owner.optJSONArray("suppressedPeers");if(hiddenRoutes==null){hiddenRoutes=new JSONArray();owner.put("suppressedPeers",hiddenRoutes);}GroupCrypto.add(hiddenRoutes,row.getString("groupPeer"));}}}saveGroupState(blockedGroups);JSONObject stones=prefs.contains("tombstones")?new JSONObject(unwrap(prefs.getString("tombstones",""))):new JSONObject();JSONArray kept=new JSONArray();for(int i=0;i<list.length();i++){JSONObject entry=list.getJSONObject(i);String id=entry.getJSONObject("config").getString("pair");if(arg!=null&&!id.equals(arg)){kept.put(entry);continue;}JSONObject state=entry.getJSONObject("state");state.remove("pending");stones.put(id,state);}if(!prefs.edit().putString("tombstones",wrap(stones.toString())).putString("profiles",wrap(kept.toString())).commit())throw new IllegalStateException();break;
            case "load":JSONObject entry=find(list,arg);if(entry!=null&&entry.optBoolean("enabled",true)){out.putString("config",entry.getJSONObject("config").toString());out.putByteArray("state",entry.getJSONObject("state").toString().getBytes(StandardCharsets.UTF_8));out.putString("peerName",entry.optString("name"));out.putLong("lastSync",entry.optLong("lastSync"));}out.putInt("textPollSeconds",prefs.getInt("textPollSeconds",2));out.putInt("attachmentPollSeconds",prefs.getInt("attachmentPollSeconds",3));out.putString("installation",installation());out.putBoolean("paused",prefs.getBoolean("paused",false));out.putLong("moduleSeenAt",prefs.getLong("moduleSeenAt",0));break;
            case "save":if(arg==null && extras!=null && extras.getByteArray("state")!=null)arg=new String(extras.getByteArray("state"),StandardCharsets.UTF_8);if(arg==null || arg.length()>600000 || c==null || !p.optBoolean("enabled",true) || extras==null || !c.getString("device").equals(extras.getString("device")))throw new IllegalStateException();JSONObject state=new JSONObject(arg);Protocol.state(c,state);p.put("state",state);save(list);break;
            case "metrics":if(c==null || !p.optBoolean("enabled",true) || extras==null || !c.getString("device").equals(extras.getString("device")))throw new IllegalStateException();if(extras.containsKey("peerName")){String name=extras.getString("peerName");if(name==null||name.length()>80)throw new IllegalArgumentException();p.put("name",name);}if(extras.containsKey("peerIdentity")){String id=extras.getString("peerIdentity");Protocol.id(id);if(!p.optString("groupPeer").isEmpty()&&!p.getString("groupPeer").equals(id))throw new SecurityException("同步组设备身份不一致");p.put("peerIdentity",id);}if(extras.containsKey("lastSync"))p.put("lastSync",extras.getLong("lastSync"));save(list);break;
            case "status":if(arg!=null&&arg.length()<120&&p!=null){p.put("status",arg);save(list);}out.putString("status",p==null?"未配置":p.optString("status","等待连接"));break;
            case "new-event":long clock=Math.addExact(prefs.getLong("event-clock",0),1);if(!prefs.edit().putLong("event-clock",clock).commit())throw new IllegalStateException();out.putLong("clock",clock);break;
            case "seen":if(c==null || extras==null)throw new IllegalStateException();Protocol.id(arg);String origin=extras.getString("origin");Protocol.id(origin);if(p.optString("peerIdentity").length()==32&&!origin.equals(p.optString("peerIdentity")))throw new SecurityException();if(p.optString("peerIdentity").isEmpty()){p.put("peerIdentity",origin);save(list);}long sourceClock=extras.getLong("eventClock");String replayOrigin=p.optString("groupKey").isEmpty()?origin:"trusted:"+p.getString("groupKey");JSONObject clocks=prefs.contains("seen-clocks")?new JSONObject(unwrap(prefs.getString("seen-clocks",""))):new JSONObject();if(sourceClock>0&&clocks.optLong(replayOrigin)>=sourceClock){out.putBoolean("first",false);break;}if(sourceClock>0){clocks.put(replayOrigin,sourceClock);if(!prefs.edit().putString("seen-clocks",wrap(clocks.toString())).commit())throw new IllegalStateException();}String event=origin+":"+arg;JSONArray seen=prefs.contains("seen")?new JSONArray(unwrap(prefs.getString("seen",""))):new JSONArray();boolean first=true;for(int i=0;i<seen.length();i++)if(event.equals(seen.getString(i)))first=false;if(first){seen.put(event);while(seen.length()>512)seen.remove(0);if(!prefs.edit().putString("seen",wrap(seen.toString())).commit())throw new IllegalStateException();}out.putBoolean("first",first);break;
            case "pause":own();if(Boolean.parseBoolean(arg)){for(int i=0;i<list.length();i++)list.getJSONObject(i).getJSONObject("state").remove("pending");save(list);}if(!prefs.edit().putBoolean("paused",Boolean.parseBoolean(arg)).commit())throw new IllegalStateException();break;
            case "heartbeat":prefs.edit().putLong("moduleSeenAt",System.currentTimeMillis()).apply();break;
            case "attachment-load":own();out.putString("state",prefs.contains("attachment-state")?unwrap(prefs.getString("attachment-state","")):"{\"outgoing\":[],\"incoming\":[]}");break;
            case "attachment-save":own();if(arg==null||arg.length()>1000000)throw new IllegalArgumentException();new JSONObject(arg);if(!prefs.edit().putString("attachment-state",wrap(arg)).commit())throw new IllegalStateException();break;
            default:throw new IllegalArgumentException();
        }
    }catch(SecurityException e){throw e;}catch(Exception e){throw new IllegalStateException("ClipBridge storage unavailable");}return out;}
    public Cursor query(Uri u,String[] p,String s,String[] a,String o){throw new SecurityException();}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){throw new SecurityException();}public int delete(Uri u,String s,String[] a){throw new SecurityException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new SecurityException();}
}
